// Merge DB session with original message data + structured state
const extractData = $('Extraer Datos').first().json;
const dbItems = $input.all();

let mensaje = extractData.mensaje || '';
try {
  const audioData = $('Armar Mensaje de Audio').first().json;
  if (audioData?.mensaje) mensaje = audioData.mensaje;
} catch(e) {}

// Parse DB session
let intent_db = 'UNKNOWN';
let history = [];
let state = {
  selected_property_id: null,
  selected_wp_post_id: null,
  selected_property_title: '',
  lead_id: null,
  appointment_id: null,
  budget: null,
  sector: '',
  tipo_propiedad: '',
  etapa: 'INICIAL',
  lead_registered: false,
  appointment_created: false,
  advisor_notified: false,
  last_tool: ''
};
let nombre = '';

if (dbItems.length > 0 && dbItems[0].json && dbItems[0].json.phone) {
  const row = dbItems[0].json;
  intent_db = row.intent || 'UNKNOWN';
  nombre = row.nombre || '';
  const raw = row.history;
  if (Array.isArray(raw)) history = raw;
  else if (typeof raw === 'string') { try { history = JSON.parse(raw); } catch(e) { history = []; } }
  else if (raw && typeof raw === 'object') history = Object.values(raw).length ? raw : [];

  state.selected_property_id = row.selected_property_id;
  state.selected_wp_post_id = row.selected_wp_post_id;
  state.selected_property_title = row.selected_property_title || '';
  state.lead_id = row.lead_id;
  state.appointment_id = row.appointment_id;
  state.budget = row.budget;
  state.sector = row.sector || '';
  state.tipo_propiedad = row.tipo_propiedad || '';
  state.etapa = row.etapa || 'INICIAL';
  state.lead_registered = !!row.lead_registered;
  state.appointment_created = !!row.appointment_created;
  state.advisor_notified = !!row.advisor_notified;
  state.last_tool = row.last_tool || '';
}

// Keep only last 4 messages
if (history.length > 4) history = history.slice(-4);

// Filter out "no tengo" contamination
history = history.filter(m => {
  if (m.role !== 'assistant') return true;
  const c = (m.content || '').toLowerCase();
  return !c.includes('por ahora no tengo') && !c.includes('no tengo algo que se ajuste');
});


// RESET STATE on new search intent — el cliente quiere algo nuevo, no continuar lo anterior
const msgLower = mensaje.toLowerCase();
const nuevaBusquedaKW = ['estoy interesado','quiero otra','busco otra','busco una','busco un','quiero ver','quiero una','quiero un','quiero comprar','muestrame otra','muéstrame otra','tienen alguna','tienes alguna','vi una propiedad','y por'];
const esNuevaBusqueda = nuevaBusquedaKW.some(k => msgLower.includes(k));
const continuaPropiedad = msgLower.includes('esa misma') || msgLower.includes('esa propiedad') || msgLower.includes('la misma') || msgLower.includes('agendar') || msgLower.includes('fotos') || msgLower.includes('detalles') || msgLower.includes('cita');

if (esNuevaBusqueda && !continuaPropiedad) {
  // El cliente quiere algo nuevo, limpia la propiedad seleccionada anterior
  state.selected_property_id = null;
  state.selected_wp_post_id = null;
  state.selected_property_title = '';
  state.sector = '';
  state.tipo_propiedad = '';
  state.budget = null;
  state.etapa = 'BUSCANDO';
  state.lead_registered = false;
  state.appointment_created = false;
  state.advisor_notified = false;
}

const tiene_sesion = (intent_db === 'COMPRADOR' || intent_db === 'VENDEDOR');

// Date context
const ahora = new Date();
const offset = -5 * 60;
const local = new Date(ahora.getTime() + ahora.getTimezoneOffset() * 60000 + offset * 60000);
const dias = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
function iso(d) { return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }

const hoy = iso(local);
const manana = new Date(local); manana.setDate(local.getDate()+1);
const pasadoManana = new Date(local); pasadoManana.setDate(local.getDate()+2);

const fecha_contexto = `📅 CONTEXTO DE FECHAS (uso interno - nunca mencionar al cliente):\nHoy: ${dias[local.getDay()]} ${local.getDate()} de ${meses[local.getMonth()]} de ${local.getFullYear()} [${hoy}]\nMañana: ${dias[manana.getDay()]} ${manana.getDate()} de ${meses[manana.getMonth()]} [${iso(manana)}]\n`;

// === Build [ESTADO ACTUAL] block — la clave del state engineering ===
const estado_actual = `[ESTADO ACTUAL — datos persistentes de la conversación]
nombre: ${nombre || 'desconocido'}
telefono: ${extractData.numero}
selected_property_id: ${state.selected_property_id || 'ninguna'}
selected_wp_post_id: ${state.selected_wp_post_id || 'ninguno'}
propiedad_titulo: ${state.selected_property_title || 'ninguna'}
sector_busqueda: ${state.sector || 'sin definir'}
tipo_propiedad: ${state.tipo_propiedad || 'sin definir'}
presupuesto: ${state.budget || 'sin definir'}
etapa: ${state.etapa}
lead_registered: ${state.lead_registered}
appointment_created: ${state.appointment_created}
advisor_notified: ${state.advisor_notified}
last_tool: ${state.last_tool || 'ninguno'}

[REGLAS DE ESTADO]
- Si lead_registered=true → NO llames registrar_lead otra vez.
- Si appointment_created=true → NO llames agendar_cita otra vez.
- Si advisor_notified=true → NO llames notificar_asesor otra vez.
- Si selected_property_id está definido → úsalo para registrar_lead, agendar_cita, obtener_detalle.
- Si selected_property_id es null y vas a registrar lead/cita → primero busca o pide al cliente que elija.
`;

return [{ json: {
  ...extractData,
  mensaje,
  nombre,
  intent_db,
  tiene_sesion,
  history_json: JSON.stringify(history),
  fecha_contexto,
  estado_actual,
  state: state
}}];

// Clasificador: COMPRADOR/VENDEDOR + SEARCH intent + entidades
const d = $input.first().json;
const msg = (d.mensaje || '').toLowerCase().trim();
const history = (() => { try { return JSON.parse(d.history_json || '[]'); } catch(e) { return []; }})();

// Intent VENDEDOR vs COMPRADOR
const venderKW = ['vender mi','quiero vender','vendo mi','tengo una propiedad para vender','poner en venta','captacion','captación'];
const avaluoKW = ['avalúo','avaluo','valuación','valoración','valor de mi','cuánto vale','cuanto vale'];
const comprarKW = ['busco','buscando','quiero una','quiero un','quiero ver','quiero comprar','me interesa una','tienes alguna','tiene alguna','tienes propiedad','crédito vip','credito vip','biess','propiedad con','casa con','vi una propiedad','vi una casa','muéstrame','muestrame'];
const saludoKW = ['hola','buenas','buenos días','buenos dias','buenas tardes','buenas noches','hi','hello','holi','que tal','qué tal'];

let intent = d.intent_db;
const esSaludoPuro = saludoKW.some(k => msg === k || msg === k+'!' || msg === k+'.' || msg === k+',');
if (esSaludoPuro) intent = 'COMPRADOR';
else if (comprarKW.some(k => msg.includes(k))) intent = 'COMPRADOR';
else if (avaluoKW.some(k => msg.includes(k))) intent = 'VENDEDOR';
else if (venderKW.some(k => msg.includes(k))) intent = 'VENDEDOR';
else if (!intent || intent === 'UNKNOWN') intent = 'COMPRADOR';

// Extraer entidades
const tiposKW = {'casa':'Casa','casas':'Casa','depto':'Departamento','departamento':'Departamento','dpto':'Departamento','dptos':'Departamento','terreno':'Terreno','terrenos':'Terreno','suite':'Suite','local':'Local','oficina':'Oficina'};
const sectoresKW = ['totoracocha','el valle','baños','ricaurte','racar','paccha','misicata','challuabamba','sinincay','yanuncay','narancay','sayausí','sayausi','don bosco','maracay','miraflores','batán','batan','baguanchi','patamarca','12 de octubre','9 de octubre','huayna capac','remigio crespo','visorrey','el plateado','nulti','feria libre'];
const vipKW = ['crédito vip','credito vip','biess','iess','amueblado','amoblado','estrenar','plusvalía','plusvalia'];

const todoHistorial = history.map(h => (h.content||'')).join(' ').toLowerCase();

let tipo_propiedad = '';
for (const [k,v] of Object.entries(tiposKW)) { if (msg.includes(k)) { tipo_propiedad = v; break; } }
if (!tipo_propiedad) for (const [k,v] of Object.entries(tiposKW)) { if (todoHistorial.includes(k)) { tipo_propiedad = v; break; } }

let ubicacion = '';
for (const s of sectoresKW) { if (msg.includes(s)) { ubicacion = s; break; } }
if (!ubicacion) for (const s of sectoresKW) { if (todoHistorial.includes(s)) { ubicacion = s; break; } }

let busqueda_libre = '';
for (const v of vipKW) { if (msg.includes(v)) { busqueda_libre = v; break; } }

let presupuesto_max = 0;
const presupuestoMatch = msg.match(/(\d{2,4})\s*mil/) || msg.match(/\$?\s?(\d{1,3}[\.,]?\d{3,})/);
if (presupuestoMatch) {
  let raw = presupuestoMatch[1].replace(/[\.,]/g,'');
  if (msg.includes('mil')) raw = raw + '000';
  presupuesto_max = parseInt(raw);
}

// Detectar SEARCH intent
const buscarKW = ['busco','buscando','quiero una','quiero un','quiero ver','muéstrame','muestrame','tienes','tiene alguna','algo en','opciones','recomiend','interesado','interesada','necesito','dame','catálogo','catalogo','propiedades','disponibles','ofreces','vi una'];

let needs_search = false;
if (intent === 'COMPRADOR') {
  // SEARCH si: hay tipo+sector, o keyword de búsqueda, o solo sector, o busqueda_libre
  const tieneTipoYSector = tipo_propiedad && ubicacion;
  const esBusquedaExplicita = buscarKW.some(k => msg.includes(k));
  const soloSector = ubicacion && !tipo_propiedad;
  const conVIP = busqueda_libre;
  needs_search = tieneTipoYSector || conVIP || (esBusquedaExplicita && (tipo_propiedad || ubicacion));
}

return [{ json: { ...d, intent, tipo_propiedad, ubicacion, busqueda_libre, presupuesto_max, needs_search } }];

// Extract structured state from agent's response and tool calls
const d = $input.first().json;
const response = d.response || d.output || '';
const intent = d.intent || 'COMPRADOR';

const extractData = $('Extraer Datos').first().json;
const resolverData = $('Resolver Sesion').first().json;
const prevState = resolverData.state || {};

const history = JSON.parse(resolverData.history_json || '[]');
history.push({ role: 'human', content: resolverData.mensaje });
// NO guardar respuestas del bot — contaminan turnos nuevos

// Try to extract state from agent intermediate steps (if available)
let state = { ...prevState };

// If Procesar Resultados ran in this turn, update selected_property_id
try {
  const procResults = $('Procesar Resultados').first().json;
  if (procResults && procResults.selected_property_id_new) {
    state.selected_property_id = procResults.selected_property_id_new;
    state.selected_wp_post_id = procResults.selected_wp_post_id_new;
    state.selected_property_title = procResults.selected_property_title_new || '';
  }
} catch(e) { /* búsqueda no se ejecutó este turno */ }


// Parse response for property mentions (wp_post_id from ?p= link)
const wpMatch = response.match(/\?p=(\d+)/);
if (wpMatch && !state.selected_wp_post_id) {
  state.selected_wp_post_id = parseInt(wpMatch[1]);
}

// Detect lead/appointment confirmation in response
if (/cita quedó registrada/i.test(response) || /cita registrada/i.test(response)) {
  state.appointment_created = true;
  state.etapa = 'CITA_AGENDADA';
}
if (/asesor te contacta|asesor te contactará/i.test(response)) {
  state.advisor_notified = true;
}

// Extract intermediate tool calls if present
try {
  const intermediateSteps = d.intermediateSteps || [];
  for (const step of intermediateSteps) {
    const toolName = step.action?.tool || '';
    const toolInput = step.action?.toolInput || {};
    state.last_tool = toolName;

    if (toolName === 'registrar_lead') {
      state.lead_registered = true;
      if (toolInput.property_id) state.selected_property_id = parseInt(toolInput.property_id);
    }
    if (toolName === 'agendar_cita') {
      state.appointment_created = true;
      state.etapa = 'CITA_AGENDADA';
    }
    if (toolName === 'notificar_asesor') {
      state.advisor_notified = true;
    }
    if (toolName === 'buscar_propiedades_pro' || toolName === 'buscar_propiedades') {
      if (toolInput.tipo_propiedad) state.tipo_propiedad = toolInput.tipo_propiedad;
      if (toolInput.ubicacion) state.sector = toolInput.ubicacion;
      if (toolInput.presupuesto_max) state.budget = parseInt(toolInput.presupuesto_max);
    }
  }
} catch(e) {}

const toStr = (v) => (v === null || v === undefined) ? '' : String(v);
const toBool = (v) => v === true ? 'true' : 'false';

return [{ json: {
  phone:         extractData.numero,
  nombre:        extractData.nombre || resolverData.nombre || '',
  intent,
  history_json:  JSON.stringify(history.slice(-10)),
  response,
  phoneNumberId: extractData.phoneNumberId,
  selected_property_id: toStr(state.selected_property_id),
  selected_wp_post_id: toStr(state.selected_wp_post_id),
  selected_property_title: toStr(state.selected_property_title),
  lead_id: toStr(state.lead_id),
  appointment_id: toStr(state.appointment_id),
  budget: toStr(state.budget),
  sector: toStr(state.sector),
  tipo_propiedad: toStr(state.tipo_propiedad),
  etapa: toStr(state.etapa) || 'INICIAL',
  lead_registered: toBool(state.lead_registered),
  appointment_created: toBool(state.appointment_created),
  advisor_notified: toBool(state.advisor_notified),
  last_tool: toStr(state.last_tool)
}}];
